// The manual's "Rastrigin function" example (section 6.3), whose engine is the one
// of its "Real function" example (6.2, and the delivered program
// jenetics.example/RealFunction.java): Codecs.ofVector, population 500,
// Mutator(0.03), MeanAlterer(0.6), other settings the defaults. Both end the
// stream with Limits.bySteadyFitness(7), a convergence criterion: an attempt ends
// after 7 generations without a better best, and the run restarts (rule 2.2; the
// "Real function" example's limit(100) is a budget, lifted). A DoubleGene stays in
// its range: Mutator draws a new value in the range, MeanAlterer takes the mean of
// two values in it (rule 2.4).
solvers.add(new Solver("ga", (budget, seed) -> evolve(
    Engine.builder((double[] x) -> {
                budget.bounds(x, problem.lower(), problem.upper());
                double value = problem.function().applyAsDouble(x);
                if (budget.record(value)) budget.solution = x.clone();
                return value;
            }, Codecs.ofVector(new DoubleRange(problem.lower(), problem.upper()), size))
        .populationSize(500)
        .optimize(Optimize.MINIMUM)
        .alterers(new Mutator<>(0.03), new MeanAlterer<>(0.6))
        .executor(Runnable::run)
        .build(),
    budget, 7, seed)));

static <G extends Gene<?, G>, C extends Comparable<? super C>> long evolve(
        Engine<G, C> engine, Budget budget, int steadyGenerations, long seed) {
    long generations = 0;
    for (int restart = 0; ; restart++) {
        if (restart > 0) seed((seed + 1) * 1_000_000 + restart);
        long[] attempt = {0};
        int[] idle = {0};
        // every generation's end, the first of each attempt (its initial population and its
        // first offspring) included: this limit comes first, so it sees every result, also
        // the one that the steady-fitness limit ends the attempt at
        var stream = engine.stream().limit(result -> {
            idle[0] = budget.evaluations == budget.generationEnd ? idle[0] + 1 : 0;
            budget.endGeneration();
            return true;
        });
        if (steadyGenerations > 0) stream = stream.limit(Limits.bySteadyFitness(steadyGenerations));
        stream
            .limit(result -> {
                attempt[0] = result.generation();
                return !budget.done() && idle[0] < STALL_GENERATIONS;
            })
            .forEach(result -> {});
        generations += attempt[0];
        if (budget.done()) return generations;
    }
}

// jmetal-algorithm examples/singleobjective/CovarianceMatrixAdaptationEvolutionStrategyRunner.java:
// the builder's defaults (λ 10, σ 0.3), with restarts (see cmaes() above)
solvers.add(new Solver("cma_es", (budget, seed) ->
    cmaes(budget, seed, problem.apply(budget), size, real.lower(), real.upper())));

static long cmaes(Budget budget, long seed, RealProblem problem, int size, double lower, double upper) {
    long generations = 0;
    for (int restart = 0; ; restart++) {
        if (restart > 0) JMetalRandom.getInstance().setSeed((seed + 1) * 1_000_000 + restart);
        // jMetal starts the mean at a random point in [0, 1)^n whatever the bounds, which is next
        // to the shifted optimum of these problems (the shift lies in [-1, 1]); the start here is
        // a random point within the bounds, like the other libraries' CMA-ES
        double[] start = new double[size];
        for (int i = 0; i < size; i++) start[i] = JMetalRandom.getInstance().nextDouble(lower, upper);
        var algorithm = new CovarianceMatrixAdaptationEvolutionStrategy.Builder(problem)
            .setMaxEvaluations(Integer.MAX_VALUE)
            .setTypicalX(start)
            .build();
        // its sampling generator is `new Random(System.currentTimeMillis())`, which a user can't
        // set: replaced by one seeded from JMetalRandom, so the same seed gives the same run
        seedCmaes(algorithm, JMetalRandom.getInstance().nextInt(0, Integer.MAX_VALUE - 1));
        long before = budget.evaluations;
        try {
            algorithm.run();
        } catch (Stop stop) {
            budget.fixedGenerations(before, algorithm.getLambda());
            return generations + (budget.evaluations - before) / algorithm.getLambda();
        } catch (ArrayIndexOutOfBoundsException error) {
            // the crash of tql2 on NaN in the covariance matrix: the workaround goes on with a
            // new attempt (see above); as is, the run ends here
            if (CMAES_AS_IS) {
                budget.fixedGenerations(before, algorithm.getLambda());
                return generations + (budget.evaluations - before) / algorithm.getLambda();
            }
        }
        // λ evaluations a generation, the initial population included
        budget.fixedGenerations(before, algorithm.getLambda());
        generations += (budget.evaluations - before) / algorithm.getLambda();
        if (budget.done()) return generations;
    }
}

